CREATE DEFINER=`root`@`localhost` FUNCTION `fn_calc_preco_venda`(codigo INT, custo DECIMAL(10,2)) RETURNS decimal(10,2)
    NO SQL
    DETERMINISTIC
BEGIN
 RETURN ROUND(custo * CASE codigo WHEN 1 THEN 1.04 WHEN 2 THEN 1.08 WHEN 3 THEN 1.10 ELSE 1 END, 2);
END$$

