DELIMITER $$
USE `estetica_bemestar`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `estetica_bemestar`.`tr_debito_estoque_atendimento_item`
BEFORE INSERT ON `estetica_bemestar`.`atendimentoitem`
FOR EACH ROW
BEGIN
 DECLARE tipo CHAR(1);
 DECLARE disponivel BOOLEAN;
 IF NEW.quantidade_itens <= 0 OR NEW.valorunitario_entrada < 0 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Quantidade ou valor inválido';
 END IF;
 SELECT tipo_item,ativo_produto_servico INTO tipo,disponivel FROM item WHERE iditem=NEW.iditem FOR UPDATE;
 IF disponivel IS NULL OR disponivel=FALSE THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Item indisponível';
 END IF;
 IF tipo='P' THEN
  UPDATE estoque SET quantidade_estoque=quantidade_estoque-NEW.quantidade_itens
   WHERE iditem=NEW.iditem AND quantidade_estoque>=NEW.quantidade_itens;
  IF ROW_COUNT()<>1 THEN
   SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Estoque insuficiente';
  END IF;
 ELSEIF NEW.quantidade_itens<>1 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Serviço deve ter quantidade 1';
 END IF;
END$$

USE `estetica_bemestar`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `estetica_bemestar`.`tr_produto_estoque`
AFTER INSERT ON `estetica_bemestar`.`produto`
